# Original lessons for Book 12 units. All dialogues, readings and exercises are newly written.

def intro(i, ar, en, bAr, bEn, ex, tr):
    return dict(id=i, kind="intro", ar=ar, en=en, bodyAr=bAr, bodyEn=bEn, example=ex, translation=tr)

def vocab(i, ar, en, words):
    return dict(id=i, kind="vocabulary", ar=ar, en=en,
                bodyAr="شاهد الصورة، واسمع النطق من زر الصوت. افتح البطاقة للمعنى والمثال، واحفظ ما تريد مراجعته.",
                bodyEn="Use the speaker to hear each word. Open a card for its meaning and example, or bookmark it for later.",
                words=words)

def choice(i, ar, en, pAr, pEn, options, answer, eAr, eEn, example=None, readEn=None, readAr=None):
    d = dict(id=i, kind="choice", ar=ar, en=en, promptAr=pAr, promptEn=pEn, options=options,
             answer=answer, explanationAr=eAr, explanationEn=eEn)
    if example: d["example"] = example
    if readEn: d["bodyEn"] = readEn; d["bodyAr"] = readAr
    return d

def listening(i, ar, en, audio, tr):
    return dict(id=i, kind="listening", ar=ar, en=en,
                bodyAr="استمع مرة، ثم استمع ببطء إذا احتجت. جرّب الفهم قبل فتح النص.",
                bodyEn="Listen once, then try the slower speed if you need it. Try listening before revealing the transcript.",
                audio=audio, translation=tr)

def grammar(i, ar, en, bAr, bEn, ex, tr, formula):
    return dict(id=i, kind="grammar", ar=ar, en=en, bodyAr=bAr, bodyEn=bEn, example=ex, translation=tr, formula=formula)

def order(i, ar, en, pAr, pEn, words, answer, eAr, eEn):
    return dict(id=i, kind="order", ar=ar, en=en, promptAr=pAr, promptEn=pEn, options=words,
                answer=answer, explanationAr=eAr, explanationEn=eEn)

def lesson(i, unit, ar, en, minutes, steps):
    return dict(id=i, ar=ar, en=en, minutes=minutes, unit=unit, steps=steps)


